      "id": "C3",
      "facts": ["F2", "F3"],
      "equity": "institutional_credibility",
      "favors": ["O1"],
      "weight": "strong",
      "why": "The Individual’s belief that he could use labeled THC products without violating policy was deemed unreasonable, undermining his credibility and raising doubts about his reliability."
    },
    {
      "id": "C4",
      "facts": ["F6"],
      "equity": "duty_to_individual",
      "favors": ["O1"],
      "weight": "weak",
      "why": "Retention of a THC product in the home at the hearing signaled ongoing access to a controlled substance, further indicating non‑abstinence."
    }
  ],
  "reasoning": {
    "read": "The Individual tested positive for marijuana metabolites after using THC‑containing transdermal and vape products for chronic back pain. He now claims he will stop, yet he still possesses a THC product and provides no objective proof of abstinence, creating a clear conflict between his assertions and the evidence.",
    "weighing": "Applying C1, the Bond Amendment creates a presumption against restoration for any unlawful user. C2 shows that none of the Guideline H mitigating conditions were satisfied—no recent drug test, no signed abstinence statement, and no demonstrated pattern of abstinence. C3 further erodes credibility because the Individual failed to appreciate the obvious controlled‑substance labeling. While C4 notes the lingering product, its weight is weaker than the statutory and guideline failures. The balance, therefore, aligns with the Administrative Judge’s finding that the security concerns remain unresolved.",
    "tradecraft": "The Administrative Judge records the decision in the official OHA docket, cites the relevant statutes and adjudicative guidelines, and issues a final written decision stating that the access authorization is not restored.",
    "uncertainty": "The record contains no contradictory evidence that would materially alter the assessment; uncertainty is minimal.",
    "handoff": "The decision is made solely by the Administrative Judge, as authorized by 10 C.F.R. § 710.7(a). No further delegation is required.",
    "tempting_wrong": {
      "option": "O4",
      "pull": "The Individual’s personal testimony about future abstinence and his claim of high job performance might tempt a grant.",
      "why_wrong": "Without objective proof of abstinence or a signed statement, granting would contravene the Bond Amendment and the explicit mitigating‑condition analysis in Guideline H."
    },
    "rejected": {
      "O2": "A request for a new drug test would not address the statutory presumption that an unlawful user cannot be cleared.",
      "O3": "Holding the case pending would delay a decision despite clear statutory and guideline findings.",
      "O4": "Granting restoration ignores the unresolved security concerns and the lack of mitigating evidence required by Guideline H."
    }
  },
  "verdict": {
    "choice": "O1",
    "basis": "settled",
    "decisive": ["C1", "C2", "C3"]
  },
  "basis_statement": "I have determined that the Individual’s access authorization should not be restored.",
  "flip_conditions": {
    "would_change": [
      {
        "id": "flip1",
        "if": "the Individual provides a recent drug test confirming abstinence from THC and a signed statement acknowledging that any future drug involvement will be grounds for revocation",
        "then": "O4",
        "why": "Both mitigating conditions under Guideline H would be satisfied, removing the security concern.",
        "origin": "authored",
        "spans": []
      }
    ],
    "would_not_change": [
      {
        "id": "noflip1",
        "if": "the Individual’s THC use had occurred only years ago and was isolated",
        "why": "The record shows recent, frequent use within the past year, which the Judge found more serious than isolated past incidents.",
        "origin": "authored",
        "spans": []
      }
    ],
    "watch_for": [
      {
        "id": "watch1",
        "what": "any future positive drug test or evidence of renewed THC use",
        "favors": ["O1"],
        "why": "Such evidence would reaffirm the Bond Amendment and Guideline H concerns.",
        "origin": "authored",
        "spans": []
      }
    ]
  },
  "lesson": "Under the Bond Amendment and Guideline H, a security clearance cannot be restored when the individual is an unlawful user of a controlled substance and fails to meet any of the prescribed mitigating conditions, such as documented abstinence or a signed commitment to abstain.",
  "limits": "This analysis applies only to cases where the individual’s drug use is recent, documented, and involves a Schedule I controlled substance; it does not address isolated, historic use that is fully disclosed and corroborated by a long period of abstinence.",
